test('issueInvoice assigns a number and changes status to issued', () => {
  const result1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const result2 = issueInvoice(result1.value, []);
  assert.equal(result2.ok, true);
  assert.equal(result2.value.status, 'issued');
  assert.equal(result2.value.number, 'INV-2026-0001');
});

test('issueInvoice uses existing numbers to find next', () => {
  const result1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const existingNumbers = ['INV-2026-0005', 'INV-2026-0001', 'INV-2026-0010'];
  const result2 = issueInvoice(result1.value, existingNumbers);
  assert.equal(result2.ok, true);
  assert.equal(result2.value.number, 'INV-2026-0011');
});

test('issueInvoice rejects non-draft invoices', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'sent',
    lines: [{ sku: 'DEV-HOUR', qty: 5, name: 'Development (hour)', unitPrice: 9500, vatRate: 21 }],
  };

  assert.deepEqual(issueInvoice(invoice, []), { ok: false, error: 'NOT_DRAFT' });
});

test('issueInvoice does not mutate the input', () => {
  const result1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const originalStatus = result1.value.status;
  assert.equal(result1.value.number, undefined);

  issueInvoice(result1.value, []);

  assert.equal(result1.value.status, originalStatus);
  assert.equal(result1.value.number, undefined);
});

